<header style="position: sticky; top: 0; z-index: 40; height: 0">
    
    <div data-layer="min" style="position: absolute; left: 0; right: 0; top: 0; transition: opacity .5s var(--out), transform .75s var(--out); opacity: 1; transform: none; animation: heroIn 1s .2s var(--soft) both">
      <div style="max-width: 1360px; margin: 0 auto; padding: 0 clamp(20px, 4vw, 40px); height: 88px; display: flex; align-items: center; justify-content: space-between; gap: 16px; color: #FCF8F3">
        <a href="/" style="display: flex; align-items: center; gap: 10px; min-height: 44px; text-decoration: none; color: inherit">
          <img src="/mam-academy-logo.svg" alt="" width="34" height="34" style="width: 34px; height: 34px">
          <span style="font-family: 'Cormorant Garamond', Georgia, serif; font-size: 26px; font-weight: 600; line-height: 1; white-space: nowrap" class="wm">MAM Academy</span>
        </a>
        <div style="display: flex; align-items: center; gap: 8px">
          <button type="button" class="btn" aria-controls="programmes-panel" style="min-height: 44px; padding: 0 16px; border-radius: 10px; background: rgba(252,248,243,.12); border: 1px solid rgba(252,248,243,.25); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); color: #FCF8F3; font: inherit; font-size: 15px; font-weight: 500; cursor: pointer; display: inline-flex; align-items: center; gap: 8px" aria-expanded="false" data-act="menu"><svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 8h16M4 16h16"></path></svg><span class="hide-xs">Menu</span><span class="sr-xs">Menu</span></button>
        </div>
      </div>
    </div>
    
    <div data-layer="full" style="position: absolute; left: 0; right: 0; top: 0; background: #FAF8F4; transition: transform .75s var(--out), box-shadow .5s ease, visibility 0s .75s; transform: translateY(-110%); visibility: hidden; box-shadow: none">
      <div style="max-width: 1360px; margin: 0 auto; padding: 0 clamp(20px, 4vw, 40px); height: 72px; display: flex; align-items: center; justify-content: space-between; gap: 24px">
        <a href="/" style="display: flex; align-items: center; gap: 10px; min-height: 44px; text-decoration: none; color: #211A13">
          <img src="/mam-academy-logo.svg" alt="" width="30" height="30" style="width: 30px; height: 30px">
          <span style="font-family: 'Cormorant Garamond', Georgia, serif; font-size: 24px; font-weight: 600; line-height: 1; white-space: nowrap" class="wm">MAM Academy</span>
        </a>
        <div style="display: flex; align-items: center; gap: 4px">
          <nav aria-label="Main" class="navlinks" style="align-items: center; gap: 4px; margin-right: 36px">
            <button type="button" class="ul" aria-controls="programmes-panel" style="min-height: 44px; margin: 0 10px; padding: 0; border: 0; background-color: transparent; font: inherit; font-size: 15px; color: #211A13; cursor: pointer; display: inline-flex; align-items: center; gap: 6px" aria-expanded="false" data-act="menu">Programmes <svg aria-hidden="true" width="11" height="11" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.6" style="transition: transform .3s; transform: rotate(0deg)"><path d="M2.5 4.5L6 8l3.5-3.5"></path></svg></button>
            <a href="/programmes#fees" class="ul" style="display: inline-flex; align-items: center; min-height: 44px; margin: 0 10px; font-size: 15px; color: #211A13; text-decoration: none">Admissions</a>
            <a href="/life" class="ul" style="display: inline-flex; align-items: center; min-height: 44px; margin: 0 10px; font-size: 15px; color: #211A13; text-decoration: none">Life at MAM</a>
            <a href="/about" class="ul" style="display: inline-flex; align-items: center; min-height: 44px; margin: 0 10px; font-size: 15px; color: #211A13; text-decoration: none">About</a>
            <a href="/portal/login" class="ul" style="display: inline-flex; align-items: center; min-height: 44px; margin: 0 10px; font-size: 15px; color: #211A13; text-decoration: none">Sign in</a>
          </nav>
          <a href="/auditer" class="btn navlinks" style="align-items: center; min-height: 40px; padding: 0 16px; border-radius: 10px; border: 1px solid #D6CCBE; color: #211A13; font-size: 15px; text-decoration: none">Visit a class</a>
          <button type="button" class="menubtn btn" aria-label="Menu" aria-controls="programmes-panel" style="width: 44px; height: 44px; align-items: center; justify-content: center; background: none; border: 0; color: #211A13; cursor: pointer" aria-expanded="false" data-act="menu"><svg aria-hidden="true" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 8h16M4 16h16"></path></svg></button>
        </div>
      </div>
      
    </div>
  </header>
